  `is_equivalence_formula` tinyint(1) DEFAULT '0',
  `prioritize_calculate_from_computed` tinyint(1) DEFAULT NULL,
  `calculation_priority` tinyint(1) NOT NULL DEFAULT '1',
  `nos_of_indicators_for_equivalence_formula` varchar(250) DEFAULT NULL,
  PRIMARY KEY (`id`),
